import React, { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, waitFor, within } from 'storybook/test';
import { ZimmSubscribeModal } from './index';

const meta: Meta<typeof ZimmSubscribeModal> = {
  title: 'Forms/ZimmSubscribeModal',
  component: ZimmSubscribeModal,
};
export default meta;
type Story = StoryObj<typeof ZimmSubscribeModal>;

/**
 * Isolated mount — open by default so the panel renders without needing a trigger. Full dialog
 * mechanics (focus entry, Tab trap, scroll lock, Escape) are Chakra Modal defaults, proven wired
 * correctly at the footer assembly level (footer/index.stories.tsx's SubscribeModalOpen);
 * testing.md says prove behaviour once, at the cheapest layer. This story is for components.md's
 * per-exported-component requirement and the visual panel.
 */
// Named component rather than an inline `render: () => { useState(...) }`. A lowercase `render`
// is not a component as far as eslint-plugin-react-hooks is concerned, so calling a hook inside
// it trips react-hooks/rules-of-hooks. Behaviour is identical — this story ignores `args`, and
// controls derive from `meta.component`, not from `render`.
const OpenSubscribeModalExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmSubscribeModal
      isOpen={isOpen}
      onClose={() => setIsOpen(false)}
      onSubmit={() => setIsOpen(false)}
      privacyPolicyHref="/privacy-policy"
    />
  );
};

export const Default: Story = {
  render: () => <OpenSubscribeModalExample />,
  play: async () => {
    // `find*`, not `get*`: useZimmModal starts `mounted: false` and ZimmModal returns null until
    // it flips in an effect, so the portal contents do not exist on the first synchronous pass.
    // `getByRole` threw before the effect had run. Queried through document.body rather than
    // canvasElement because ZimmModal renders via createPortal — testing.md's canvasElement rule
    // can't reach a portal root, which is why the scope was already widened here.
    const doc = within(document.body);
    const dialog = await doc.findByRole('dialog');
    await expect(dialog).toBeInTheDocument();

    // Chakra's Modal fades/scales in (framer-motion) rather than appearing instantly — the
    // dialog node exists in the DOM from the start of that transition, at opacity: 0. Waiting
    // only for `findByRole('dialog')` above lets this story's a11y check (which runs right
    // after `play` returns) sample the DOM mid-fade, where text is still semi-transparent —
    // axe then measures a blended, falsely-low colour-contrast ratio against real, passing
    // tokens. Wait for the transition to actually settle first.
    await waitFor(() => expect(dialog).toHaveStyle({ opacity: '1' }));

    await expect(await doc.findByRole('heading', { name: /join us/i })).toBeInTheDocument();
    await expect(await doc.findByRole('link', { name: /privacy policy/i })).toBeInTheDocument();
  },
};

