25	 * Override of the base retail-react-app hook of the same name (identical public behaviour,
26	 * ported to TypeScript with a generic payload type).
27	 *
28	 * @param params closeOnRouteChange / resetDataOnClose options
29	 * @returns open state, payload, and open/close handlers
30	 */
31	export const useModalState = <TData = unknown>({
32	  closeOnRouteChange = true,
33	  resetDataOnClose = true,
34	}: UseModalStateParams = {}): UseModalStateReturn<TData> => {
35	  const [state, setState] = useState<{ isOpen: boolean; data: TData | null }>({
36	    isOpen: false,
37	    data: null,
38	  });
39	
40	  const { pathname } = useLocation();
41	
42	  useEffect(() => {
43	    if (closeOnRouteChange) {
44	      setState((prev) => (prev.isOpen ? { isOpen: false, data: resetDataOnClose ? null : prev.data } : prev));
45	    }
46	  }, [pathname, closeOnRouteChange, resetDataOnClose]);
47	
48	  return {
49	    isOpen: state.isOpen,
50	    data: state.data,
51	    onOpen: (data: TData) => {
52	      setState({ isOpen: true, data });
53	    },
54	    onClose: () => {
55	      setState((prev) => ({
56	        isOpen: false,
57	        data: resetDataOnClose ? null : prev.data,
58	      }));
59	    },
60	  };
