6	const ZIMM_TABS_RECIPE = 'ZimmTabs';
7	
8	export type ZimmTabItem = {
9	  /** Stable id used for activeTabId and the onTabChange callback. */
10	  id: string;
11	  /** Visible label — Contentful-driven per tab, so length varies and drives the overflow check. */
12	  label: string;
