import { breakpoints } from 'app/theme/foundation';

// Figma pdp/drawer/header inset, measured: Small & Mobile share 32px/40px at every width;
// Large only widens to 64px/48px at/above the tablet breakpoint (mobile-first baseStyle below
// is the compact numbers, matching how ZimmDrawer's own close button collapses the same way).
const PADDING_COMPACT = { x: 'var(--zimm-scale-2xl)', y: 'var(--zimm-scale-3xl)' };
const PADDING_LARGE = { x: 'var(--zimm-scale-4xl)', y: 'var(--zimm-scale-1200)' };

export const ZimmTabs = {
  parts: ['header', 'menu', 'navItem', 'navItemActive', 'navigationIconGroup'],
  baseStyle: {
    header: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      gap: 'var(--zimm-scale-xs)',
      paddingInline: PADDING_COMPACT.x,
      paddingBlock: PADDING_COMPACT.y,
      // Leaves room for ZimmDrawer's own absolutely-positioned close button in the corner.
      paddingRight: 'var(--zimm-scale-3xl)',
      flexShrink: 0,
    },
    menu: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-xl)',
      overflowX: 'hidden',
      scrollBehavior: 'smooth',
      minWidth: 0,
    },
    navItem: {
      textStyle: 'navigation',
      whiteSpace: 'nowrap',
      flexShrink: 0,
      background: 'none',
      border: 'none',
      cursor: 'pointer',
      padding: 0,
      color: 'var(--zimm-color-text-secondary)',
    },
    navItemActive: {
      color: 'var(--zimm-color-text-default)',
      textDecoration: 'underline',
    },
    navigationIconGroup: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-2xs)',
      flexShrink: 0,
    },
  },
  variants: {
    large: {
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          paddingInline: PADDING_LARGE.x,
          paddingBlock: PADDING_LARGE.y,
        },
      },
    },
    small: {},
    mobile: {},
  },
};
